import json
recs=[json.loads(l) for l in open('experiment_logs/rollout_records.jsonl')]
for r in recs:
    for li,leaf in enumerate(r['tito_session_mismatch']):
        for m in leaf or []:
            if '<tool_call>' in m['expected_text']:
                e=m['expected_text']; a=m['actual_text']
                print("rollout",r['sample_index'],"leaf",li,"seg",m['segment_index'])
                print("EXPECTED tail:",repr(e[-500:]))
                print("ACTUAL   tail:",repr(a[len(e)-200:][:900]))
                print('----')
# leaf-level: statuses, exit statuses, mismatch counts per leaf
import collections
